import{_ as a,H as o,f as c,i as d}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"Plan（计划）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/skills/plan.md","filePath":"zh/skills/plan.md"}'),t={name:"zh/skills/plan.md"};function s(n,e,p,l,i,r){return o(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="plan-计划" tabindex="-1">Plan（计划） <a class="header-anchor" href="#plan-计划" aria-label="Permalink to &quot;Plan（计划）&quot;">​</a></h1><p><code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>。引用规范；不要复述。</p><p>如果未解决的规范笔记影响实现或任务顺序，回到 <code>design</code>。</p><h2 id="里程碑任务-30-60-分钟每个" tabindex="-1">里程碑任务（30-60 分钟每个） <a class="header-anchor" href="#里程碑任务-30-60-分钟每个" aria-label="Permalink to &quot;里程碑任务（30-60 分钟每个）&quot;">​</a></h2><p>每个任务是 <code>- [ ] T&lt;n&gt;: &lt;名&gt;</code> —— 总是复选框，不是标题。<code>tdd</code>/<code>subagents</code> 完成时改为 <code>- [x]</code>；<code>ship</code> 拒绝运行直到所有 <code>- [ ]</code> 完成。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goal:       &lt;一句话&gt;</span></span>
<span class="line"><span>files:      &lt;路径&gt;</span></span>
<span class="line"><span>acceptance: &lt;测试或命令&gt;</span></span>
<span class="line"><span>spec:       &lt;docs/staging/specs/...#anchor&gt;</span></span></code></pre></div><p>无精确代码。无步骤。Acceptance 可执行：测试名、命令或脚本检查。每个任务留下仓库是绿色的。</p><p>标记独立任务：<code>[parallel] T3, T4, T5</code>。</p><p>仅当共享契约、状态、错误和 acceptance 闭合时标记 <code>[parallel]</code>。</p><p><strong>原子展开在分派时推迟</strong> - <code>subagents</code> 在分派时将里程碑展开为 2-5 分钟步骤，不在这里。</p><p><strong>新项目</strong>：派生初始化任务 —— 搭脚手架代码、测试、CI，总是包括：<code>README.md</code>、<code>CHANGELOG.md</code>、<code>.gitignore</code> 和 <code>Makefile</code>（或等价的任务运行器配置）。</p><h2 id="不要放在计划里" tabindex="-1">不要放在计划里 <a class="header-anchor" href="#不要放在计划里" aria-label="Permalink to &quot;不要放在计划里&quot;">​</a></h2><p>背景、架构、理由（规范）、CI 命令、复制粘贴的 acceptance。</p><h2 id="滚动波浪" tabindex="-1">滚动波浪 <a class="header-anchor" href="#滚动波浪" aria-label="Permalink to &quot;滚动波浪&quot;">​</a></h2><p>规范有 <code>## Roadmap</code>？仅展开标记为 <code>← 现在详细计划</code> 的里程碑。留下其他的为 stub。</p><p><code>ship</code> 后：把 <code>← 现在详细计划</code> 标记移到下一个里程碑（改它的 <code>← stub</code> 为 <code>← 现在详细计划</code>），根据你学到的更新它，然后展开它。仅当里程碑目标实质改变时回到 <code>design</code>。</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code> 必须存在于磁盘前移交给 <code>tdd</code>/<code>subagents</code>。</p><p>与用户确认计划。</p><p>多数 <code>[parallel]</code> → <code>subagents</code>。否则 → <code>tdd</code>。</p>`,20)])])}const u=a(t,[["render",s]]);export{g as __pageData,u as default};
